{"content":"//! Versioned, immutable element store.
//!
//! Invariants:
//! - Element `(id, version)` pairs are immutable once admitted.
//! - Retiring an element removes it from the *active gallery* but the
//!   resolver still serves pinned references until an operator accepts a
//!   migration. This prevents gemma's mint-on-use churn from breaking views.
//! - The active gallery is capped at 200; of those, at most `STABLE_CORE_MAX`
//!   carry [`super::dsl::Tier::StableCore`] and may not be retired by gemma.
//! - The most recent good snapshot is cached so a CatalogService outage does
//!   not blank the UI.

use std::collections::HashMap;
use std::sync::{Arc, RwLock};

use super::dsl::{Element, ElementId, ElementVersion, PinnedRef, Tier};

pub const GALLERY_SIZE: usize = 200;
pub const STABLE_CORE_MAX: usize = 40;

#[derive(Debug, Clone, Default)]
pub struct CatalogSnapshot {
    /// All (id, version) we have ever seen — resolves pinned refs forever.
    pub elements: HashMap<(ElementId, ElementVersion), Element>,
    /// Currently active gallery: at most `GALLERY_SIZE` ids, latest version each.
    pub active: HashMap<ElementId, ElementVersion>,
}

impl CatalogSnapshot {
    pub fn resolve(&self, pin: &PinnedRef) -> Option<&Element> {
        self.elements.get(&(pin.id.clone(), pin.version))
    }

    pub fn latest_active(&self, id: &ElementId) -> Option<&Element> {
        let v = self.active.get(id)?;
        self.elements.get(&(id.clone(), *v))
    }

    pub fn stable_core_count(&self) -> usize {
        self.active
            .iter()
            .filter_map(|(id, v)| self.elements.get(&(id.clone(), *v)))
            .filter(|e| matches!(e.tier, Tier::StableCore))
            .count()
    }
}

#[derive(Debug, Clone, Default)]
pub struct CatalogStore {
    inner: Arc<RwLock<CatalogSnapshot>>,
}

impl CatalogStore {
    pub fn new() -> Self { Self::default() }

    /// Snapshot for read-only consumers (views, interpreter).
    pub fn snapshot(&self) -> CatalogSnapshot {
        self.inner.read().expect("catalog store poisoned").clone()
    }

    /// Admit a freshly minted element from gemma. Returns the prior version
    /// if this id already existed (callers may want to log migrations).
    pub fn admit(&self, element: Element) -> Option<ElementVersion> {
        let mut g = self.inner.write().expect("catalog store poisoned");
        let prior = g.active.get(&element.id).copied();
        // Immutable insert into the resolver table.
        g.elements
            .entry((element.id.clone(), element.version))
            .or_insert_with(|| element.clone());
        // Active gallery promotion.
        g.active.insert(element.id.clone(), element.version);
        prior
    }

    /// Retire an element from the active gallery. Pinned refs still resolve.
    /// Stable-core elements are protected and silently refused.
    pub fn retire(&self, id: &ElementId) -> bool {
        let mut g = self.inner.write().expect("catalog store poisoned");
        if let Some(v) = g.active.get(id).copied() {
            if let Some(el) = g.elements.get_mut(&(id.clone(), v)) {
                if matches!(el.tier, Tier::StableCore) {
                    return false;
                }
                el.retired = true;
            }
            g.active.remove(id);
            true
        } else {
            false
        }
    }
}
"}

{"content":"//! json-render.dev DSL → egui interpreter.
//!
//! This is the **only** code path allowed to draw widgets in the operator
//! console. Every view binds via [`render`] with a `PinnedRef` resolved from
//! the live [`CatalogSnapshot`]. Unknown ids, missing versions, or unknown
//! DSL nodes surface as [`RenderError`] — no silent fallbacks, no raw JSON.
//!
//! The seed primitive set below is the minimum needed for gemma_brain to
//! generate against. Adding a new primitive is a deliberate act: append a
//! match arm here and document the DSL key in the json-render.dev catalog
//! contract. Never extend by accepting unknown node shapes.

use egui::{RichText, Ui};
use serde_json::Value;
use thiserror::Error as ThisError;

use super::dsl::PinnedRef;
use super::store::CatalogSnapshot;
use crate::theme::*;

#[derive(Debug, ThisError)]
pub enum RenderError {
    #[error("catalog element {id}@{version} not found")]
    UnknownElement { id: String, version: u32 },
    #[error("catalog spec missing or malformed `kind` field")]
    MalformedSpec,
    #[error("unknown DSL node kind `{0}` — not in json-render.dev catalog")]
    UnknownKind(String),
    #[error("schema/value mismatch for element {0}")]
    SchemaMismatch(String),
}

/// Render a bound element. `value` is the live JSON payload (typically from
/// `grpc::decode_to_json`); `snapshot` is the current `CatalogStore` view.
pub fn render(
    ui: &mut Ui,
    snapshot: &CatalogSnapshot,
    pin: &PinnedRef,
    value: &Value,
) -> Result<(), RenderError> {
    let element = snapshot.resolve(pin).ok_or_else(|| RenderError::UnknownElement {
        id: pin.id.clone(),
        version: pin.version,
    })?;
    walk(ui, &element.spec, value)
}

fn walk(ui: &mut Ui, spec: &Value, value: &Value) -> Result<(), RenderError> {
    let kind = spec.get("kind").and_then(Value::as_str).ok_or(RenderError::MalformedSpec)?;
    match kind {
        // ---------- layout primitives ----------
        "stack" => {
            let dir = spec.get("dir").and_then(Value::as_str).unwrap_or("v");
            let children = spec.get("children").and_then(Value::as_array).cloned().unwrap_or_default();
            let render_children = |ui: &mut Ui| -> Result<(), RenderError> {
                for child in &children { walk(ui, child, value)?; }
                Ok(())
            };
            let mut out = Ok(());
            if dir == "h" {
                ui.horizontal(|ui| out = render_children(ui));
            } else {
                ui.vertical(|ui| out = render_children(ui));
            }
            out
        }

        // ---------- text ----------
        "label" => {
            let bind = spec.get("bind").and_then(Value::as_str);
            let text = match bind {
                Some(path) => json_pointer(value, path)
                    .and_then(|v| v.as_str().map(|s| s.to_string()))
                    .unwrap_or_default(),
                None => spec.get("text").and_then(Value::as_str).unwrap_or("").to_string(),
            };
            ui.label(RichText::new(text).color(FG).size(12.0));
            Ok(())
        }

        // ---------- status pill (stable-core) ----------
        "status_pill" => {
            let bind = spec.get("bind").and_then(Value::as_str).ok_or(RenderError::MalformedSpec)?;
            let v = json_pointer(value, bind).cloned().unwrap_or(Value::Null);
            let (label, color) = match v.as_str().unwrap_or("") {
                "ok" | "up" | "healthy"   => ("OK", OK),
                "warn" | "degraded"       => ("WARN", WARN),
                "err" | "down" | "failed" => ("ERR", DANGER),
                other if !other.is_empty() => (other, MUTED),
                _                          => ("—", MUTED),
            };
            ui.label(RichText::new(label).strong().monospace().size(11.0).color(color));
            Ok(())
        }

        // ---------- action button (stable-core) ----------
        "button" => {
            let label = spec.get("label").and_then(Value::as_str).unwrap_or("action");
            // Mutation dispatch lands when InvokeHandle integration is wired.
            let _ = ui.button(label);
            Ok(())
        }

        other => Err(RenderError::UnknownKind(other.to_string())),
    }
}

/// Minimal `/foo/bar/0` JSON pointer lookup used by `bind`.
fn json_pointer<'a>(value: &'a Value, path: &str) -> Option<&'a Value> {
    if path.is_empty() || path == "/" { return Some(value); }
    let normalized = if path.starts_with('/') { path.to_string() } else { format!("/{path}") };
    value.pointer(&normalized)
}
"}

{"content":"//! json-render.dev declarative element spec.
//!
//! An `Element` is an immutable, versioned UI atom authored by `gemma_brain`.
//! The Rust interpreter in [`super::interpret`] is the only thing allowed to
//! materialise these into pixels — no per-element Rust, no WASM, no fallback.

use serde::{Deserialize, Serialize};
use serde_json::Value;

/// Stable identifier minted by gemma_brain. Never reused.
pub type ElementId = String;

/// Monotonic per-element version. A new version means a behavioural change;
/// the previous version is still resolvable via the immutable store so views
/// pinned to an older version keep working until an operator accepts migration.
pub type ElementVersion = u32;

/// A view's binding target. Always pinned — unpinned references are a smell.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq, Hash)]
pub struct PinnedRef {
    pub id: ElementId,
    pub version: ElementVersion,
}

/// Catalog membership classification.
///
/// `StableCore` elements are immune to gemma's mint-on-retire churn — they
/// are the primitives operators rely on (button, toggle, select, numeric
/// input, table row, status pill, log line, form field, ...). Of the 200
/// gallery slots, ~40 are reserved as stable core; the remaining ~160 are
/// gemma's novelty playground and may rotate.
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum Tier {
    StableCore,
    Novelty,
}

/// One catalog element. The `spec` field is the json-render.dev DSL payload
/// the interpreter walks. We keep it as `serde_json::Value` so the DSL can
/// evolve without forcing a `zeroclaw-gui` rebuild — the interpreter handles
/// unknown nodes by surfacing a `RenderError`, never by guessing.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Element {
    pub id: ElementId,
    pub version: ElementVersion,
    pub tier: Tier,
    /// Human label for the gallery view. Not shown to operators by default.
    pub title: String,
    /// Optional accepted-schema fingerprint. Bindings whose schema does not
    /// match are rejected before render.
    pub accepts_schema_hash: Option<String>,
    /// json-render.dev DSL tree. Walked by [`super::interpret::render`].
    pub spec: Value,
    /// Lifecycle bookkeeping populated by `CatalogStore` (not by gemma).
    #[serde(default)]
    pub retired: bool,
}

impl Element {
    pub fn pin(&self) -> PinnedRef {
        PinnedRef { id: self.id.clone(), version: self.version }
    }
}
"}

{"content":"//! `ActiveReflectionCatalog` — the bridge-owned mutable layer that
//! tonic-reflection's immutable `Builder` cannot be (whitepaper: "Why
//! tonic-reflection Builder Is Not Enough").
//!
//! The catalog owns active plugin blobs and answers reflection queries:
//! `list_services` advertises only active blobs (no phantom services);
//! `file_by_filename` / `symbol_by_name` serve borrowed descriptor bytes
//! sliced straight out of the sealed blob images (zero-copy).
//!
//! Persistence is the per-object shm layout that replaces monolithic
//! `/dev/shm/live-schema.json`:
//!
//! ```text
//! /dev/shm/opdbus/plugin-blobs/<plugin_id>.<schema_hash16>.blob
//! ```

use crate::blob::{BlobManifest, BlobRef, PluginObjectBlob};
use crate::descriptor;
use std::collections::HashMap;
use std::io;
use std::path::{Path, PathBuf};

pub const DEFAULT_SHM_DIR: &str = "/dev/shm/opdbus/plugin-blobs";

/// Catalog manifest filename — the atomic commit point of the blob dir.
/// `{ catalog_hash, generation, plugins: { <plugin_id>: <schema_hash> } }`.
/// `catalog_hash` is a blake3 leaf-fold over the sorted per-blob schema
/// hashes; it is computed HERE and only here — consumers read it, never
/// re-hash (one-schema rule).
pub const MANIFEST_FILENAME: &str = ".manifest.json";

struct Entry {
    path: PathBuf,
    /// Sealed blob image; descriptor lookups return subslices of this.
    bytes: Vec<u8>,
    manifest: BlobManifest,
    /// file name -> (offset, len) of the FileDescriptorProto within `bytes`.
    files: HashMap<String, (usize, usize)>,
    /// fully-qualified symbol -> file name.
    symbols: HashMap<String, String>,
}

pub struct ActiveReflectionCatalog {
    dir: PathBuf,
    entries: HashMap<String, Entry>,
}

/// Durable blob store. It keeps the historical `BlobStore` name while allowing
/// typed blob families in one store namespace. Today the active-reflection
/// family is backed by `ActiveReflectionCatalog`.
pub struct BlobStore {
    active_reflection: ActiveReflectionCatalog,
}

impl BlobStore {
    pub fn open(dir: impl Into<PathBuf>) -> io::Result<Self> {
        Ok(Self {
            active_reflection: ActiveReflectionCatalog::open(dir)?,
        })
    }

    pub fn open_default() -> io::Result<Self> {
        Self::open(DEFAULT_SHM_DIR)
    }

    pub fn write(&mut self, blob: &PluginObjectBlob) -> io::Result<PathBuf> {
        match blob.manifest.blob_type.as_str() {
            "active_reflection" => self.active_reflection.upsert_blob(blob),
            other => Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                format!("unsupported blob type: {other}"),
            )),
        }
    }

    pub fn remove_blob(&mut self, plugin_id: &str) -> io::Result<bool> {
        self.active_reflection.remove_blob(plugin_id)
    }

    pub fn retain_plugins(
        &mut self,
        keep: &std::collections::HashSet<String>,
    ) -> io::Result<Vec<String>> {
        self.active_reflection.retain_plugins(keep)
    }

    pub fn catalog_hash(&self) -> String {
        self.active_reflection.catalog_hash()
    }

    pub fn list_services(&self) -> Vec<String> {
        self.active_reflection.list_services()
    }

    pub fn active_plugins(&self) -> Vec<String> {
        self.active_reflection.active_plugins()
    }

    pub fn manifest(&self, plugin_id: &str) -> Option<&BlobManifest> {"}

{"content":"    /// Reflection `ListServices`: only active blobs, sorted.
    pub fn list_services(&self) -> Vec<String> {
        let mut v: Vec<String> = self
            .entries
            .values()
            .flat_map(|e| e.manifest.grpc.services.iter().cloned())
            .collect();
        v.sort();
        v
    }

    pub fn active_plugins(&self) -> Vec<String> {
        let mut v: Vec<String> = self.entries.keys().cloned().collect();
        v.sort();
        v
    }

    /// Reflection `file_by_filename`: borrowed `FileDescriptorProto` bytes.
    pub fn file_by_filename(&self, filename: &str) -> Option<&[u8]> {
        self.entries.values().find_map(|e| {
            e.files
                .get(filename)
                .map(|(off, len)| &e.bytes[*off..*off + *len])
        })
    }

    /// Reflection `file_containing_symbol`.
    pub fn symbol_by_name(&self, symbol: &str) -> Option<&[u8]> {
        self.entries.values().find_map(|e| {
            e.symbols
                .get(symbol)
                .and_then(|file| e.files.get(file))
                .map(|(off, len)| &e.bytes[*off..*off + *len])
        })
    }

    pub fn manifest(&self, plugin_id: &str) -> Option<&BlobManifest> {
        self.entries.get(plugin_id).map(|e| &e.manifest)
    }

    pub fn dir(&self) -> &Path {
        &self.dir
    }

    /// Paths of all active blob artifacts (input to btrfs sealing).
    pub fn blob_paths(&self) -> Vec<PathBuf> {
        let mut v: Vec<PathBuf> = self.entries.values().map(|e| e.path.clone()).collect();
        v.sort();
        v
    }

    /// Rehydrate every active blob as an owned `PluginObjectBlob`, sorted by
    /// plugin id — the startup-hydration input for in-memory reflection.
    pub fn plugin_object_blobs(&self) -> Vec<PluginObjectBlob> {
        let mut ids: Vec<&String> = self.entries.keys().collect();
        ids.sort();
        ids.iter()
            .filter_map(|id| PluginObjectBlob::from_sealed(&self.entries[*id].bytes).ok())
            .collect()
    }
}

/// Read ONE plugin's canonical schema straight from its sealed blob in `dir`
/// — the single-plugin read path (no catalog load, no monolith file). This is
/// how a component (including a plugin reading its own contract) asks "what
/// is plugin X": the blob answers, nothing else does.
pub fn read_plugin_state_store_schema(
    dir: &Path,
    plugin_id: &str,
) -> Option<op_state_store::PluginSchema> {
    let prefix = format!("{plugin_id}.");
    for e in std::fs::read_dir(dir).ok()? {
        let p = e.ok()?.path();
        let Some(name) = p.file_name().and_then(|n| n.to_str()) else {
            continue;
        };
        if name.starts_with(&prefix) && name.ends_with(".blob") {
            let bytes = std::fs::read(&p).ok()?;
            let blob = BlobRef::new(&bytes).ok()?;
            return blob.state_store_schema().ok();
        }"}

{"content":"//! Model-agnostic generative UI gallery system.
//!
//! This crate implements a model-agnostic inference loop that reads sealed plugin blobs,
//! accepts operator guidance via Antigravity chat UI, and generates json-render.dev specs
//! rendered by the existing DSL interpreter.
//!
//! # Architecture
//!
//! 1. **Context Assembler** — Gathers baseline context (blobs, docs, catalog)
//! 2. **Inference Loop** — Calls ZeroClaw `/v1/chat/completions` with tool support
//! 3. **Spec Validator** — Validates generated specs against grammar
//! 4. **Gallery Admission** — Admits validated specs to catalog store
//!
//! # Model Agnosticism
//!
//! No model-specific code. Any model exposed through ZeroClaw can be used. Model selection
//! is ZeroClaw's responsibility via the zeroclaw plugin's `selected_provider` and
//! `selected_model` fields.

pub mod admission;
pub mod context;
pub mod inference;
pub mod tools;
pub mod validator;

pub use admission::GalleryAdmission;
pub use context::{GenerationContext, SchemaPayload};
pub use inference::InferenceLoop;
pub use validator::SpecValidator;

/// Gallery generation configuration
#[derive(Debug, Clone, serde::Deserialize)]
pub struct GalleryGenConfig {
    /// Target number of specs to generate (default: 200)
    pub target_count: usize,

    /// Maximum stable-core elements to protect (default: 40)
    pub stable_core_max: usize,

    /// ZeroClaw HTTP endpoint (default: "http://localhost:8082")
    pub zeroclaw_endpoint: String,

    /// Enable MCP tool layer for cross-blob discovery
    pub enable_mcp: bool,

    /// Enable Qdrant semantic search
    pub enable_qdrant: bool,

    /// Maximum inference turns per spec (default: 10)
    pub max_turns: usize,
}

impl Default for GalleryGenConfig {
    fn default() -> Self {
        Self {
            target_count: 200,
            stable_core_max: 40,
            zeroclaw_endpoint: "http://localhost:8082".to_string(),
            enable_mcp: false,
            enable_qdrant: false,
            max_turns: 10,
        }
    }
}
"}

{"content":"//! Zeroclaw route helpers backed by the SHM state tree.

use anyhow::{bail, Result};
use simd_json::prelude::*;

use crate::state_tree;

#[derive(Debug, Clone)]
pub struct ZeroclawRoute {
    pub provider: String,
    pub upstream_provider: String,
    pub transport: Option<String>,
    pub model: String,
    pub hint: Option<String>,
    pub kind: Option<String>,
    pub status: String,
    pub available: bool,
    pub status_reason: Option<String>,
    pub source: Option<String>,
}

impl ZeroclawRoute {
    fn from_value(value: &simd_json::OwnedValue) -> Option<Self> {
        let model = value.get("model")?.as_str()?.to_string();
        let provider = value
            .get("provider")
            .and_then(|v| v.as_str())
            .unwrap_or("zeroclaw")
            .to_string();
        let upstream_provider = value
            .get("upstream_provider")
            .and_then(|v| v.as_str())
            .unwrap_or(&provider)
            .to_string();
        let status = value
            .get("status")
            .and_then(|v| v.as_str())
            .unwrap_or("declared")
            .to_string();
        let available = value
            .get("available")
            .and_then(|v| v.as_bool())
            .unwrap_or_else(|| status == "available");

        Some(Self {
            provider,
            upstream_provider,
            transport: value
                .get("transport")
                .and_then(|v| v.as_str())
                .map(str::to_string),
            model,
            hint: value
                .get("hint")
                .and_then(|v| v.as_str())
                .map(str::to_string),
            kind: value
                .get("kind")
                .and_then(|v| v.as_str())
                .map(str::to_string),
            status,
            available,
            status_reason: value
                .get("status_reason")
                .and_then(|v| v.as_str())
                .map(str::to_string),
            source: value
                .get("source")
                .and_then(|v| v.as_str())
                .map(str::to_string),
        })
    }
}

pub fn routes() -> Option<Vec<ZeroclawRoute>> {
    let zeroclaw = state_tree::read_plugin("zeroclaw")?;
    let route_values = zeroclaw.get("model_routes")?.as_array()?;
    Some(
        route_values
            .iter()
            .filter_map(ZeroclawRoute::from_value)
            .collect(),
    )
}

pub fn route_for_model(model: &str) -> Option<ZeroclawRoute> {
    routes()?.into_iter().find(|route| route.model == model)
}

pub fn ensure_model_available(model: &str) -> Result<()> {
    if let Some(route) = route_for_model(model) {
        if !route.available {
            let reason = route
                .status_reason
                .unwrap_or_else(|| "route is not available".to_string());
            bail!(
                "Zeroclaw route '{}' is {} but not available: {}",
                model,
                route.status,
                reason
            );
        }
    }

    Ok(())
}
"}

{"content":"//! Chat session management

use chrono::{DateTime, Utc};
use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::RwLock;
use uuid::Uuid;

use op_core::ChatMessage;

/// A chat session containing message history
#[derive(Debug, Clone)]
pub struct ChatSession {
    pub id: String,
    pub name: Option<String>,
    pub messages: Vec<ChatMessage>,
    pub created_at: DateTime<Utc>,
    pub updated_at: DateTime<Utc>,
    pub metadata: HashMap<String, simd_json::OwnedValue>,
    /// Auth session ID (from WireGuard gateway)
    pub auth_session_id: Option<String>,
    /// Is this a controller session (you/chatbot)
    pub is_controller: bool,
    /// WireGuard peer public key
    pub peer_pubkey: Option<String>,
    /// Container ID for memory scoping (work/home/barmitzvah)
    pub container_id: Option<String>,
}

impl ChatSession {
    /// Create a new chat session
    pub fn new() -> Self {
        let now = Utc::now();
        Self {
            id: Uuid::new_v4().to_string(),
            name: None,
            messages: Vec::new(),
            created_at: now,
            updated_at: now,
            metadata: HashMap::new(),
            auth_session_id: None,
            is_controller: false,
            peer_pubkey: None,
            container_id: None,
        }
    }

    /// Create with a specific ID
    pub fn with_id(id: impl Into<String>) -> Self {
        let now = Utc::now();
        Self {
            id: id.into(),
            name: None,
            messages: Vec::new(),
            created_at: now,
            updated_at: now,
            metadata: HashMap::new(),
            auth_session_id: None,
            is_controller: false,
            peer_pubkey: None,
            container_id: None,
        }
    }

    /// Create authenticated session (from gateway)
    pub fn authenticated(
        auth_session_id: String,
        is_controller: bool,
        peer_pubkey: Option<String>,
    ) -> Self {
        let now = Utc::now();
        Self {
            id: Uuid::new_v4().to_string(),
            name: None,
            messages: Vec::new(),
            created_at: now,
            updated_at: now,
            metadata: HashMap::new(),
            auth_session_id: Some(auth_session_id),
            is_controller,
            peer_pubkey,
            container_id: None,
        }
    }

    /// Check if session has controller access
    pub fn can_access_compact_mcp(&self) -> bool {
        self.is_controller
    }

    /// Add a message to the session
    pub fn add_message(&mut self, message: ChatMessage) {
        self.messages.push(message);
        self.updated_at = Utc::now();
    }

    /// Get the last N messages
    pub fn last_messages(&self, n: usize) -> &[ChatMessage] {
        let start = self.messages.len().saturating_sub(n);"}

