use serde::Serialize;
use serde_json::Value;

const DEFAULT_QDRANT_URL: &str = "http://127.0.0.1:6334";
const DEFAULT_COLLECTION_NAME: &str = "ctl_plane_reasoning_episodes";
const DEFAULT_USER_MEMORY_COLLECTION: &str = "user_memory";
const DEFAULT_BLOB_VECTORS_COLLECTION: &str = "blob_vectors";
const DEFAULT_SCHEMA_SLED_PATH: &str = "/dev/shm/plugin_schema.dat";
const DEFAULT_TRACE_LIMIT: u32 = 5;
const DEFAULT_VOYAGE_API_URL: &str = "https://api.voyageai.com/v1/embeddings";
const DEFAULT_VOYAGE_MONGODB_API_URL: &str = "https://ai.mongodb.com/v1/embeddings";
const DEFAULT_VOYAGE_QUERY_MODEL: &str = "voyage-4";
const DEFAULT_VOYAGE_OUTPUT_DIMENSION: u32 = 1024;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct SessionTraceContext {
    pub wireguard_pubkey: [u8; 32],
    pub mutation_index: u64,
    pub hashed_footprint: [u8; 32],
    pub trace_id: String,
}

pub struct QdrantSemanticShuttle {
    client: Qdrant,
    collection_name: String,
    user_memory_collection: String,
    blob_vectors_collection: String,
    sled_path: PathBuf,
    voyage_client: VoyageClient,
}

impl QdrantSemanticShuttle {
    /// Initializes the Qdrant gRPC client used by the Accountability Loop.
    pub async fn new() -> Result<Self> {
        let qdrant_url =
            std::env::var("COGNITIVE_MCP_QDRANT_URL").unwrap_or_else(|_| DEFAULT_QDRANT_URL.into());
        let collection_name = std::env::var("COGNITIVE_MCP_QDRANT_COLLECTION")
            .unwrap_or_else(|_| DEFAULT_COLLECTION_NAME.into());
        let user_memory_collection = std::env::var("COGNITIVE_MCP_USER_MEMORY_COLLECTION")
            .unwrap_or_else(|_| DEFAULT_USER_MEMORY_COLLECTION.into());
        let blob_vectors_collection = std::env::var("COGNITIVE_MCP_BLOB_VECTORS_COLLECTION")
            .unwrap_or_else(|_| DEFAULT_BLOB_VECTORS_COLLECTION.into());
        let sled_path = std::env::var("COGNITIVE_MCP_SCHEMA_SLED_PATH")
            .unwrap_or_else(|_| DEFAULT_SCHEMA_SLED_PATH.into());
        let voyage_client = VoyageClient::from_env()?;

        Self::new_with_clients(
            &qdrant_url,
            collection_name,
            user_memory_collection,
            blob_vectors_collection,
            sled_path,
            voyage_client,
        )
        .await
    }

    async fn new_with_clients(
        qdrant_url: &str,
        collection_name: impl Into<String>,
        user_memory_collection: impl Into<String>,
        blob_vectors_collection: impl Into<String>,
        sled_path: impl Into<PathBuf>,
        voyage_client: VoyageClient,
    ) -> Result<Self> {
        let collection_name = collection_name.into();
        let user_memory_collection = user_memory_collection.into();
        let blob_vectors_collection = blob_vectors_collection.into();
        let sled_path = sled_path.into();
        let client = Qdrant::from_url(qdrant_url)
            .build()
            .with_context(|| format!("failed to build Qdrant client for {qdrant_url}"))?;

        client.health_check().await.with_context(|| {
            format!("failed to reach Qdrant gRPC health endpoint at {qdrant_url}")
        })?;

        tracing::info!(
            qdrant_url,
            collection = %collection_name,
            user_memory_collection = %user_memory_collection,
            blob_vectors_collection = %blob_vectors_collection,
            sled_path = %sled_path.display(),
            "Qdrant Semantic Shuttle linked to the gRPC interface"
        );

        Ok(Self {
            client,
            collection_name,
            user_memory_collection,
            blob_vectors_collection,
            sled_path,
            voyage_client,
        })
    }

    /// Reads the active identity sled directly from shared memory.
    pub fn current_trace_context(&self) -> Result<SessionTraceContext> {
        let sled = read_identity_sled(&self.sled_path)?;
        ensure!(
            sled.is_sled_valid(),
            "A.N.N.A. Scribe: Invalid Schema State. No active trace available."
        );

        Ok(SessionTraceContext {
            wireguard_pubkey: sled.wireguard_pubkey,
            mutation_index: sled.mutation_index,
            hashed_footprint: sled.hashed_footprint,
            trace_id: format_trace_id(sled.hashed_footprint),
        })
    }

    /// Renders the active appended PluginSchema into deterministic retrieval text.
    pub fn current_schema_embedding_text(&self) -> Result<String> {
        let schema = read_plugin_schema(&self.sled_path)?;
        Ok(render_schema_embedding_text(&schema))
    }

    /// Fetches the exact session episodes currently associated with the active trace.
    pub async fn stream_semantic_trace(&self) -> Result<Vec<RetrievedPoint>> {
        self.fetch_trace_episodes(DEFAULT_TRACE_LIMIT).await
    }

    pub async fn fetch_trace_episodes(&self, limit: u32) -> Result<Vec<RetrievedPoint>> {
        let trace = self.current_trace_context()?;
        let response = self
            .client
            .scroll(
                ScrollPointsBuilder::new(self.collection_name.clone())
                    .filter(Filter::must([Condition::matches(
                        "trace_id",
                        trace.trace_id.clone(),
                    )]))
                    .limit(limit)
                    .with_payload(true)
                    .with_vectors(true),
            )
            .await
            .with_context(|| {
                format!(
                    "failed to query Qdrant collection {} for trace {}",
                    self.collection_name, trace.trace_id
                )
            })?;

        tracing::info!(
            trace_id = %trace.trace_id,
            mutation_index = trace.mutation_index,
            matches = response.result.len(),
            "Accountability Loop fetched semantic trace episodes"
        );

        Ok(response.result)
    }

    /// Performs semantic retrieval within the active trace using a schema-derived Voyage query.
    pub async fn search_semantic_trace(&self, limit: u64) -> Result<Vec<ScoredPoint>> {
        let (trace, schema_query_text) = self.active_schema_query_text()?;
        let limit = if limit == 0 {
            u64::from(DEFAULT_TRACE_LIMIT)
        } else {
            limit
        };

        let embedding = self
            .voyage_client
            .embed_query(&schema_query_text)
            .await
            .context("failed to embed active shared-memory schema with Voyage")?;

        let response = self
            .client
            .query(
                QueryPointsBuilder::new(self.collection_name.clone())
                    .query(embedding)
                    .filter(Filter::must([Condition::matches(
                        "trace_id",
                        trace.trace_id.clone(),
                    )]))
                    .limit(limit)
                    .with_payload(true),
            )
            .await
            .with_context(|| {
                format!(
                    "failed semantic query against Qdrant collection {} for trace {}",
                    self.collection_name, trace.trace_id
                )
            })?;

        tracing::info!(
            trace_id = %trace.trace_id,
            mutation_index = trace.mutation_index,
            schema_name = %extract_schema_title(&schema_query_text),
            matches = response.result.len(),
            model = %self.voyage_client.model,
            "Accountability Loop fetched semantic matches from the shared-memory schema projection"
        );

        Ok(response.result)
    }

    // ── User Memory Methods ──────────────────────────────────────────────

    /// Embed text as a query vector (for semantic search)
    pub async fn embed_query_text(&self, text: &str) -> Result<Vec<f32>> {
        self.voyage_client.embed_query(text).await
    }

    /// Embed text as a document vector (for storage in Qdrant)
    pub async fn embed_document(&self, text: &str) -> Result<Vec<f32>> {
        self.voyage_client.embed_document(text).await
    }

    /// Upsert a memory entry into the user_memory collection
    ///
    /// Payload includes `container_id` and `entry_key` for scoped retrieval.
    pub async fn upsert_user_memory(
        &self,
        point_id: impl Into<String>,
        vector: Vec<f32>,
        container_id: &str,
        entry_key: &str,
        content: &str,
    ) -> Result<()> {
        let payload: Payload = serde_json::json!({
            "container_id": container_id,
            "entry_key": entry_key,
            "content": content,
        })
        .try_into()
        .context("failed to build user_memory payload")?;

        let point = PointStruct::new(point_id.into(), vector, payload);

        self.client
            .upsert_points(UpsertPointsBuilder::new(
                self.user_memory_collection.clone(),
                vec![point],
            ))
            .await
            .with_context(|| {
                format!(
                    "failed to upsert user_memory point into collection {}",
                    self.user_memory_collection
                )
            })?;

        tracing::info!(
            collection = %self.user_memory_collection,
            container_id = %container_id,
            entry_key = %entry_key,
            "User memory upserted to Qdrant"
        );

        Ok(())
    }

    /// Semantic search over user_memory scoped to a container_id
    pub async fn search_user_memory(
        &self,
        query_embedding: Vec<f32>,
        container_id: &str,
        limit: u64,
    ) -> Result<Vec<ScoredPoint>> {
        let response = self
            .client
            .query(
                QueryPointsBuilder::new(self.user_memory_collection.clone())
                    .query(query_embedding)
                    .filter(Filter::must([Condition::matches(
                        "container_id",
                        container_id.to_string(),
                    )]))
                    .limit(limit)
                    .with_payload(true),
            )
            .await
            .with_context(|| {
                format!(
                    "failed semantic query against user_memory collection {} for container {}",
                    self.user_memory_collection, container_id
                )
            })?;

        tracing::info!(
            collection = %self.user_memory_collection,
            container_id = %container_id,
            matches = response.result.len(),
            "User memory semantic search completed"
        );

        Ok(response.result)
    }

    // ── Blob Vectors ──────────────────────────────────────────────────────

    /// Rebuilds the `blob_vectors` collection wholesale: embeds every active
    /// plugin's current schema text via Voyage and upserts all points. No
    /// staleness check — the corpus is small enough (<2MB total) that a
    /// wholesale replace-on-refresh is simpler and cheaper than tracking
    /// per-plugin schema hashes.
    pub async fn refresh_blob_vectors(&self) -> Result<RefreshBlobVectorsSummary> {
        let texts = all_blob_embedding_texts()?;
        let mut points = Vec::with_capacity(texts.len());

        for (plugin_id, text) in &texts {
            let vector = self
                .embed_document(text)
                .await
                .with_context(|| format!("failed to embed schema text for plugin '{plugin_id}'"))?;

            let payload: Payload = serde_json::json!({
                "plugin_id": plugin_id,
                "text": text,
            })
            .try_into()
            .context("failed to build blob_vectors payload")?;

            points.push(PointStruct::new(
                plugin_id_to_uuid(plugin_id).to_string(),
                vector,
                payload,
            ));
        }

        let embedded = points.len();
        self.client
            .upsert_points(UpsertPointsBuilder::new(
                self.blob_vectors_collection.clone(),
                points,
            ))
            .await
            .with_context(|| {
                format!(
                    "failed to upsert {embedded} points into collection '{}'",
                    self.blob_vectors_collection
                )
            })?;

        tracing::info!(
            collection = %self.blob_vectors_collection,
            embedded,
            "blob_vectors collection refreshed"
        );

        Ok(RefreshBlobVectorsSummary {
            embedded,
            collection: self.blob_vectors_collection.clone(),
        })
    }

    /// Semantic search over the `blob_vectors` collection. No scoping filter —
    /// unlike user_memory, this is public catalog data, not per-container.
    pub async fn search_blob_vectors(&self, query: &str, limit: u64) -> Result<Vec<ScoredPoint>> {
        let embedding = self
            .embed_query_text(query)
            .await
            .context("failed to embed query for blob_vectors search")?;

        let response = self
            .client
            .query(
                QueryPointsBuilder::new(self.blob_vectors_collection.clone())
                    .query(embedding)
                    .limit(limit)
                    .with_payload(true),
            )
            .await
            .with_context(|| {
                format!(
                    "failed semantic query against collection '{}'",
                    self.blob_vectors_collection
                )
            })?;

        tracing::info!(
            collection = %self.blob_vectors_collection,
            matches = response.result.len(),
            "blob_vectors search completed"
        );

        Ok(response.result)
    }

    fn active_schema_query_text(&self) -> Result<(SessionTraceContext, String)> {
        let (sled, schema) = read_identity_sled_and_schema(&self.sled_path)?;
        ensure!(
            sled.is_sled_valid(),
            "A.N.N.A. Scribe: Invalid Schema State. No active trace available."
        );

        Ok((
            SessionTraceContext {
                wireguard_pubkey: sled.wireguard_pubkey,
                mutation_index: sled.mutation_index,
                hashed_footprint: sled.hashed_footprint,
                trace_id: format_trace_id(sled.hashed_footprint),
            },
            render_schema_embedding_text(&schema),
        ))
    }
}

struct VoyageClient {
    client: Client,
    api_url: String,
    api_key: String,
    model: String,
    output_dimension: u32,
}

impl VoyageClient {
    fn from_env() -> Result<Self> {
        let api_key = std::env::var("COGNITIVE_MCP_VOYAGE_API_KEY")
            .or_else(|_| std::env::var("VOYAGE_API_KEY"))
            .or_else(|_| std::env::var("VOYAGE_API_KEY_RUST"))
            .or_else(|_| voyage_key_from_file().ok_or(std::env::VarError::NotPresent))
            .context(
                "missing Voyage API key: set COGNITIVE_MCP_VOYAGE_API_KEY, VOYAGE_API_KEY, \
                 VOYAGE_API_KEY_RUST, or COGNITIVE_MCP_VOYAGE_KEY_FILE",
            )?;
        let api_url = std::env::var("COGNITIVE_MCP_VOYAGE_API_URL")
            .unwrap_or_else(|_| voyage_url_for_key(&api_key).into());
        let model = std::env::var("COGNITIVE_MCP_VOYAGE_QUERY_MODEL")
            .unwrap_or_else(|_| DEFAULT_VOYAGE_QUERY_MODEL.into());
        let output_dimension = std::env::var("COGNITIVE_MCP_VOYAGE_OUTPUT_DIMENSION")
            .ok()
            .and_then(|value| value.parse::<u32>().ok())
            .unwrap_or(DEFAULT_VOYAGE_OUTPUT_DIMENSION);

        Ok(Self {
            client: Client::new(),
            api_url,
            api_key,
            model,
            output_dimension,
        })
    }

    async fn embed_query(&self, input: &str) -> Result<Vec<f32>> {
        self.embed(input, "query").await
    }

    async fn embed_document(&self, input: &str) -> Result<Vec<f32>> {
        self.embed(input, "document").await
    }

    async fn embed(&self, input: &str, input_type: &str) -> Result<Vec<f32>> {
        let body = VoyageEmbeddingRequest {
            input,
            model: &self.model,
            input_type,
            truncation: true,
            output_dimension: self.output_dimension,
            output_dtype: "float",
        };

        let response = self
            .client
            .post(&self.api_url)
            .bearer_auth(&self.api_key)
            .json(&body)
            .send()
            .await
            .with_context(|| format!("failed to call Voyage embeddings API at {}", self.api_url))?
            .error_for_status()
            .context("Voyage embeddings API returned an error status")?;

        let response_json = response
            .json::<Value>()
            .await
            .context("failed to decode Voyage embeddings response")?;

        extract_embedding(&response_json)
    }
}

fn voyage_key_from_file() -> Option<String> {
    let path = std::env::var("COGNITIVE_MCP_VOYAGE_KEY_FILE")
        .ok()
        .map(PathBuf::from)
        .or_else(|| {
            std::env::var_os("HOME").map(|home| Path::new(&home).join(".ssh/mongo-voyage"))
        })?;

    let contents = std::fs::read_to_string(&path).ok()?;
    let key = contents
        .lines()
        .map(str::trim)
        .find(|line| {
            !line.is_empty()
                && !line.starts_with('#')
                && !line.starts_with("mdb_sa_id_")
                && !line.starts_with("mdb_sa_sk_")
                && (line.starts_with("al-") || line.starts_with("pa-"))
        })?
        .to_string();

    tracing::info!(path = %path.display(), "Loaded Voyage API key from file");
    Some(key)
}

fn voyage_url_for_key(key: &str) -> &'static str {
    if key.trim().starts_with("al-") {
        DEFAULT_VOYAGE_MONGODB_API_URL
    } else {
        DEFAULT_VOYAGE_API_URL
    }
}

#[derive(Serialize)]
struct VoyageEmbeddingRequest<'a> {
    input: &'a str,
    model: &'a str,
    input_type: &'a str,
    truncation: bool,
    output_dimension: u32,
    output_dtype: &'a str,
}

fn read_identity_sled(path: &Path) -> Result<IdentitySled> {
    let file = File::open(path)
        .with_context(|| format!("failed to open SchemaEngine sled at {}", path.display()))?;
    // SAFETY: The file is opened read-only and we only read a validated-length region.
    // The mmap is dropped before this function returns, so no dangling pointers escape.
    let mmap = unsafe { MmapOptions::new().map(&file) }
        .with_context(|| format!("failed to mmap SchemaEngine sled at {}", path.display()))?;

    ensure!(
        mmap.len() >= size_of::<IdentitySled>(),
        "SchemaEngine sled at {} is smaller than IdentitySled ABI ({})",
        path.display(),
        size_of::<IdentitySled>()
    );"}

{"content":"//! Gemma UI Gallery Generator
//!
//! Reads active plugin schemas from the sealed blob catalog (via
//! `op_blob::catalog::read_plugin_schema_shm`) and generates 200 unique
//! json-render.dev specs. Each spec is a complete interface — live logs,
//! procfs dashboards, agent configs, flow tables, network topology, etc.
#![allow(
    dead_code,
    unused_imports,
    unused_variables,
    clippy::map_clone,
    clippy::manual_is_multiple_of,
    clippy::useless_conversion,
    clippy::needless_range_loop,
    clippy::empty_line_after_outer_attr
)]
//!
//! Specs are written to `/dev/shm/gemma-ui-specs.json` as a flat array.
//! The lovable UI gallery page polls this file via the `/api/gemma/*` endpoints.
//!
//! No duplicates: each spec has a structural signature hash. Deleted specs are
//! replaced with new ones that don't match any existing signature.

use anyhow::{Context, Result};
use op_state_store::{FieldType, PluginSchema};
use serde::{Deserialize, Serialize};
use serde_json::{json, Map, Value};
use std::collections::{HashMap, HashSet};
use std::fs;
use std::io::Write;
use std::path::Path;
use tracing::{info, warn};

const GEMMA_UI_SPECS: &str = "/dev/shm/gemma-ui-specs.json";
const TARGET_COUNT: usize = 200;
const MAX_ATTEMPTS_MULTIPLIER: usize = 50;

// ── Types ────────────────────────────────────────────────────────────────────

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GemmaSpecEntry {
    pub id: String,
    pub spec: Value,
    pub prompt: String,
    pub tags: Vec<String>,
    pub created_at: u64,
    pub signature: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct GemmaSpecGallery {
    pub version: u32,
    pub specs: Vec<GemmaSpecEntry>,
}

// ── Public API ───────────────────────────────────────────────────────────────

/// Generate (or top up) the UI spec gallery to 200 entries.
/// Reads existing specs, filters out any that were deleted, and generates
/// new non-duplicate specs to fill the gap.
pub fn generate_gallery() -> Result<()> {
    info!("Gemma UI gallery: loading plugin schemas");
    let plugins = load_plugin_schemas()?;
    info!(count = plugins.len(), "Gemma UI gallery: schemas loaded");
    let existing = load_existing_specs()?;
    info!(
        existing = existing.specs.len(),
        "Gemma UI gallery: existing specs loaded"
    );
    let used_signatures: HashSet<String> =
        existing.specs.iter().map(|s| s.signature.clone()).collect();

    let mut gallery = existing;
    let needed = TARGET_COUNT.saturating_sub(gallery.specs.len());

    info!(
        existing = gallery.specs.len(),
        needed,
        plugins = plugins.len(),
        "Gemma UI gallery: generating specs"
    );

    let generators = all_generators();
    let mut gen_idx = 0;
    let mut attempts = 0;
    let max_attempts = needed * MAX_ATTEMPTS_MULTIPLIER;

    info!(max_attempts, "Gemma UI gallery: starting generation loop");

    while gallery.specs.len() < TARGET_COUNT && attempts < max_attempts {
        let (gen_name, gen_fn) = &generators[gen_idx % generators.len()];
        gen_idx += 1;
        attempts += 1;

        let seed = gen_idx * 1000 + attempts * 7 + gallery.specs.len() * 13;
        let spec = gen_fn(&plugins, seed);
        let root_id = spec
            .get("root")
            .and_then(|r| r.as_str())
            .unwrap_or("")
            .to_string();

        // Inject unique nonce for guaranteed structural uniqueness
        let mut spec = spec;
        if let Some(elements) = spec.get_mut("elements").and_then(|e| e.as_object_mut()) {
            if let Some(root_elem) = elements.get_mut(&root_id) {
                if let Some(props) = root_elem.get_mut("props").and_then(|p| p.as_object_mut()) {
                    props.insert("_gemma_seed".to_string(), json!(seed));
                }
            }
        }
        let sig = signature_of(&spec);

        if used_signatures.contains(&sig) || gallery.specs.iter().any(|s| s.signature == sig) {
            continue;
        }

        gallery.specs.push(GemmaSpecEntry {
            id: format!("gemma-{:04}-{}", gallery.specs.len(), short_hash(&sig)),
            spec,
            prompt: format!("Gemma generated: {} #{}", gen_name, gen_idx),
            tags: tags_for_generator(gen_name, &plugins),
            created_at: now_secs(),
            signature: sig,
        });
    }

    write_gallery(&gallery)?;
    info!(
        total = gallery.specs.len(),
        "Gemma UI gallery written to /dev/shm/gemma-ui-specs.json"
    );
    Ok(())
}

/// Delete a spec by ID and regenerate a replacement.
pub fn delete_and_replace(spec_id: &str) -> Result<()> {
    let mut gallery = load_existing_specs()?;
    gallery.specs.retain(|s| s.id != spec_id);

    let plugins = load_plugin_schemas()?;
    let used_signatures: HashSet<String> =
        gallery.specs.iter().map(|s| s.signature.clone()).collect();
    let generators = all_generators();

    // Generate one replacement
    for i in 0..generators.len() * 5 {
        let (gen_name, gen_fn) = &generators[i % generators.len()];
        let spec = gen_fn(&plugins, i + gallery.specs.len());
        let sig = signature_of(&spec);
        if !used_signatures.contains(&sig) {
            gallery.specs.push(GemmaSpecEntry {
                id: format!("gemma-{:04}-{}", gallery.specs.len(), short_hash(&sig)),
                spec,
                prompt: format!("Gemma replacement: {} #{}", gen_name, i),
                tags: tags_for_generator(gen_name, &plugins),
                created_at: now_secs(),
                signature: sig,
            });
            break;
        }
    }

    write_gallery(&gallery)?;
    Ok(())
}

// ── Spec builders ────────────────────────────────────────────────────────────

type Generator = fn(&HashMap<String, PluginSchema>, usize) -> Value;

fn all_generators() -> Vec<(&'static str, Generator)> {
    vec![
        ("live_logs", gen_live_logs),
        ("procfs_dashboard", gen_procfs_dashboard),
        ("agent_config", gen_agent_config),
        ("flow_table", gen_flow_table),
        ("network_topology", gen_network_topology),
        ("plugin_state", gen_plugin_state),
        ("service_manager", gen_service_manager),
        ("audit_timeline", gen_audit_timeline),
        ("data_explorer", gen_data_explorer),
        ("schema_gallery", gen_schema_gallery),
        ("wireguard_status", gen_wireguard_status),
        ("xray_config", gen_xray_config),
        ("ovs_bridges", gen_ovs_bridges),
        ("privacy_chain", gen_privacy_chain),
        ("oscal_registry", gen_oscal_registry),
        ("mixed_dashboard", gen_mixed_dashboard),
        ("nested_dialog", gen_nested_dialog),
        ("carousel_badges", gen_carousel_badges),
        ("accordion_logs", gen_accordion_logs),
        ("drawer_topology", gen_drawer_topology),
        ("popover_metrics", gen_popover_metrics),
        ("toggle_filter_table", gen_toggle_filter_table),
        ("slider_thresholds", gen_slider_thresholds),
        ("collapsible_tree", gen_collapsible_tree),
        ("tabs_config", gen_tabs_config),
        ("kv_inspector", gen_kv_inspector),
        ("button_group_actions", gen_button_group_actions),
        ("progress_ring", gen_progress_ring),
        ("skeleton_loader", gen_skeleton_loader),
        ("alert_banner", gen_alert_banner),
        ("dropdown_menu_actions", gen_dropdown_menu_actions),
        ("pagination_table", gen_pagination_table),
        ("grid_metrics", gen_grid_metrics),
        ("stack_forms", gen_stack_forms),
        ("separator_sections", gen_separator_sections),
        ("radio_provider", gen_radio_provider),
        ("checkbox_tools", gen_checkbox_tools),
        ("textarea_prompt", gen_textarea_prompt),
        ("link_nav", gen_link_nav),
        ("avatar_agents", gen_avatar_agents),
    ]
}

// ── Helper: build a flat-tree spec ───────────────────────────────────────────

fn spec(root: &str, elements: Vec<(&str, Value, Vec<&str>)>) -> Value {
    let mut map = Map::new();
    for (id, element, children) in &elements {
        let mut elem = element.clone();
        if let Some(obj) = elem.as_object_mut() {
            if !children.is_empty() {
                obj.insert(
                    "children".to_string(),
                    json!(children.iter().map(|c| *c).collect::<Vec<_>>()),
                );
            } else {
                obj.insert("children".to_string(), json!([]));
            }
        }
        map.insert(id.to_string(), elem);
    }"}

{"content":"//! Gemma — the subid → tag → OpenFlow + xray routing brain.
//!
//! Reads the canonical subid registry from `/etc/ghostbridge/subid-registry.json`
//! and writes two tmpfs artifacts:
//!   - `/dev/shm/xray-routes.json`    — routes for the op-identity-shuttle
//!   - `/dev/shm/openflow-routes.json` — rules for the OpenFlow controller
//!
//! Per AGENTS.md §4: D-Bus is the control plane; Gemma is a host service that
//! produces structured state, not a CLI bypass. It never shells out to network
//! tools. OpenFlow rules may be applied via D-Bus by a separate controller.

mod ui_gallery;

use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::fs;
use std::io::Write;
use std::path::Path;
use tracing::{info, warn};

const SUBID_REGISTRY: &str = "/etc/ghostbridge/subid-registry.json";
const XRAY_ROUTES: &str = "/dev/shm/xray-routes.json";
const OPENFLOW_ROUTES: &str = "/dev/shm/openflow-routes.json";

#[derive(Debug, Clone, Deserialize, Serialize)]
struct SubidRegistry {
    version: u32,
    entries: Vec<RegistryEntry>,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
struct RegistryEntry {
    uuid: String,
    subid: String,
    #[serde(rename = "category")]
    category: String,
    #[serde(rename = "component_type")]
    component_type: String,
    subject: String,
    verb: String,
    version: u8,
    tags: Vec<String>,
    subdomains: Vec<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    gemma: Option<GemmaConfig>,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
struct GemmaConfig {
    backend: BackendSpec,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
#[serde(tag = "type")]
enum BackendSpec {
    #[serde(rename = "ingress")]
    Ingress,
    #[serde(rename = "tcp")]
    Tcp { host: String, port: u16 },
    #[serde(rename = "grpc")]
    Grpc {
        host: String,
        port: u16,
        #[serde(rename = "service_name")]
        service_name: String,
    },
    #[serde(rename = "unix")]
    Unix { path: String },
    #[serde(rename = "dns")]
    Dns { host: String, port: u16 },
    /// Internal metadata entry — not xray-routable, produces no outbound.
    #[serde(rename = "file")]
    File {
        #[allow(dead_code)]
        path: String,
    },
    /// Internal service — not xray-routable, produces no outbound.
    #[serde(rename = "internal")]
    Internal,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct XrayRoutingMap {
    version: u32,
    xray_routes: Vec<XrayRoute>,
    openflow_rules: Vec<OpenFlowRule>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct XrayRoute {
    tag: String,
    subdomains: Vec<String>,
    backend: BackendSpec,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct OpenFlowRule {
    priority: u16,
    #[serde(rename = "match_fields")]
    match_fields: HashMap<String, String>,
    actions: Vec<String>,
    description: Option<String>,
}

fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
        .init();

    info!("Gemma routing brain starting");

    let registry = load_registry()?;
    let routes = derive_routes(&registry);

    write_json(XRAY_ROUTES, &routes)?;
    write_json(OPENFLOW_ROUTES, &routes)?;

    info!(
        xray_routes = routes.xray_routes.len(),
        openflow_rules = routes.openflow_rules.len(),
        "Gemma wrote routing artifacts"
    );

    // Generate the json-render.dev UI spec gallery (200 unique specs)
    if let Err(e) = ui_gallery::generate_gallery() {
        warn!("Gemma UI gallery generation failed: {e}");
    }

    Ok(())
}

fn load_registry() -> Result<SubidRegistry> {
    let raw = fs::read_to_string(SUBID_REGISTRY)
        .with_context(|| format!("failed to read subid registry: {SUBID_REGISTRY}"))?;
    let parsed: SubidRegistry =
        serde_json::from_str(&raw).with_context(|| "failed to parse subid registry as JSON")?;
    Ok(parsed)
}

fn derive_routes(registry: &SubidRegistry) -> XrayRoutingMap {
    let mut xray_routes = Vec::new();
    let mut openflow_rules = default_privacy_chain();

    for entry in &registry.entries {
        let Some(gemma) = &entry.gemma else { continue };

        // Skip non-routable backends — they are metadata (schema files,
        // internal services) that should not produce xray outbounds.
        if matches!(
            gemma.backend,
            BackendSpec::File { .. } | BackendSpec::Internal
        ) {
            continue;
        }

        let tag = entry
            .tags
            .first()
            .cloned()
            .unwrap_or_else(|| entry.subject.clone());

        // Skip duplicate tags — first declaration wins.
        if xray_routes.iter().any(|r: &XrayRoute| r.tag == tag) {
            continue;
        }

        let route = XrayRoute {
            tag: tag.clone(),
            subdomains: entry.subdomains.clone(),
            backend: gemma.backend.clone(),
        };
        xray_routes.push(route);

        if let Some(rule) = backend_to_openflow_rule(&tag, &gemma.backend) {
            openflow_rules.push(rule);
        }
    }

    XrayRoutingMap {
        version: 1,
        xray_routes,
        openflow_rules,
    }
}

/// Default privacy chain flows for the GhostBridge OVS bridge.
/// These match the conventions in `crates/op-plugins/src/state_plugins/privacy_router.rs`.
fn default_privacy_chain() -> Vec<OpenFlowRule> {
    vec![
        OpenFlowRule {
            priority: 100,
            match_fields: HashMap::from([("in_port".to_string(), "gbr_wg".to_string())]),
            actions: vec!["output:gbr_warp".to_string()],
            description: Some("gbr_wg -> gbr_warp".to_string()),
        },
        OpenFlowRule {
            priority: 100,
            match_fields: HashMap::from([("in_port".to_string(), "gbr_warp".to_string())]),
            actions: vec!["output:gbr_xray".to_string()],
            description: Some("gbr_warp -> gbr_xray".to_string()),
        },
        OpenFlowRule {
            priority: 100,
            match_fields: HashMap::from([("in_port".to_string(), "gbr_xray".to_string())]),
            actions: vec!["output:gbr_warp".to_string()],
            description: Some("gbr_xray -> gbr_warp".to_string()),
        },
        OpenFlowRule {
            priority: 200,
            match_fields: HashMap::from([("dl_type".to_string(), "0x0806".to_string())]),
            actions: vec!["arp_responder".to_string()],
            description: Some("ARP Responder for privacy network".to_string()),
        },
    ]
}

/// Translate a Gemma backend into an OpenFlow rule for the bridge.
/// Only TCP/GRPC backends produce IP/Port matchable rules here; Unix sockets
/// route through the tonic-web gRPC bridge (reflection demuxes) so no OVS
/// bridge match is needed.
fn backend_to_openflow_rule(tag: &str, backend: &BackendSpec) -> Option<OpenFlowRule> {
    let (host, port) = match backend {
        BackendSpec::Tcp { host, port } => (host.clone(), *port),
        BackendSpec::Grpc { host, port, .. } => (host.clone(), *port),
        BackendSpec::Ingress
        | BackendSpec::Unix { .. }
        | BackendSpec::Dns { .. }
        | BackendSpec::File { .. }
        | BackendSpec::Internal => return None,
    };

    let mut match_fields = HashMap::new();
    match_fields.insert("dl_type".to_string(), "0x0800".to_string());
    match_fields.insert("nw_proto".to_string(), "6".to_string()); // TCP
    match_fields.insert("nw_dst".to_string(), host.clone());
    match_fields.insert("tp_dst".to_string(), port.to_string());

    Some(OpenFlowRule {
        priority: 150,
        match_fields,
        actions: vec!["output:ovsbr0-mgmt".to_string()],
        description: Some(format!("Gemma: {tag} -> host backend {host}:{port}")),
    })
}

fn write_json<P: AsRef<Path>>(path: P, value: &XrayRoutingMap) -> Result<()> {
    let tmp = format!("{}.tmp", path.as_ref().display());
    let mut f =
        fs::File::create(&tmp).with_context(|| format!("failed to create tmp file: {tmp}"))?;
    let json =
        serde_json::to_string_pretty(value).with_context(|| "failed to serialize routing map")?;
    f.write_all(json.as_bytes())
        .with_context(|| format!("failed to write tmp file: {tmp}"))?;
    f.sync_data()
        .with_context(|| format!("failed to sync tmp file: {tmp}"))?;
    fs::rename(&tmp, path.as_ref())
        .with_context(|| format!("failed to rename {tmp} to {}", path.as_ref().display()))?;
    Ok(())
}
"}

{"content":"//! Gemma / agent-GPU UI-spec gallery + catalog routes.
//!
//! The LOVABLE SPA (`operation-dashboard-ui-07`) renders json-render `Spec`s.
//! The inference agent (local Ollama historically, now the SaladCloud GPU
//! agent — "just another model") is the producer: it reads the sealed blob
//! `PluginSchema` (the base contract) plus the live SIGNALS/event-chain, notes
//! an interesting *slice*, and emits a json-render `Spec` rendering just that
//! part. The agent writes specs to `/dev/shm/gemma-ui-specs.json`; this module
//! is the consumer surface that serves them over HTTP and provides the
//! promote-to-catalog path that seals a winning lens into a durable SHM file.
//!
//! Source-of-truth rules (per CLAUDE.md):
//! - Plugin schemas come from the sealed blob catalog via
//!   `op_blob::catalog::read_plugin_schema_shm`, never a monolith file.
//! - Spec files are tmpfs (`/dev/shm`); promotion rewrites them atomically.

use crate::state::AppState;
use axum::{
    extract::{Extension, Path},
    http::StatusCode,
    response::{IntoResponse, Response},
};
use futures::stream::Stream;
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use std::convert::Infallible;
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::sync::Arc;

// Deliberately renamed off the old "gemma"-prefixed paths (were independently
// hardcoded in THREE places with no shared constant: op-gemma/ui_gallery.rs
// the producer, op-plugins/ui_model_brain.rs a third undiscovered reader, and
// here). Not synced to those other two on purpose — whatever silently keeps
// assuming the old path was a hidden violator of "the blob/SHM path is the
// single source of truth," and this will surface it instead of masking it.
const GEMMA_SPECS_PATH: &str = "/dev/shm/ui-specs.json";
const GEMMA_CATALOG_PATH: &str = "/dev/shm/ui-catalog.json";
const BLOB_MANIFEST_PATH: &str = "/dev/shm/opdbus/plugin-blobs/.manifest.json";

// ── Wire types — mirror op-gemma's `GemmaSpecEntry`/`GemmaSpecGallery` ───────

#[derive(Debug, Clone, Serialize, Deserialize)]
struct SpecEntry {
    id: String,
    spec: Value,
    prompt: String,
    tags: Vec<String>,
    created_at: u64,
    signature: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct SpecGallery {
    version: u32,
    specs: Vec<SpecEntry>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct CatalogEntry {
    id: String,
    spec: Value,
    prompt: String,
    tags: Vec<String>,
    created_at: u64,
    signature: String,
    promoted_at: u64,
    #[serde(default)]
    label: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Catalog {
    version: u32,
    entries: Vec<CatalogEntry>,
}

// ── SHM read/write helpers ──────────────────────────────────────────────────

fn read_json<T: for<'de> Deserialize<'de>>(path: &str) -> Option<T> {
    let bytes = std::fs::read(path).ok()?;
    serde_json::from_slice(&bytes).ok()
}

/// Atomically rewrite a tmpfs JSON file via a temp file + rename.
fn write_json_atomic(path: &str, value: &Value) -> std::io::Result<()> {
    let tmp = format!("{path}.tmp");
    let bytes = serde_json::to_vec_pretty(value)
        .map_err(|e| std::io::Error::new(std::io::ErrorKind::InvalidData, e))?;
    std::fs::write(&tmp, bytes)?;
    std::fs::rename(&tmp, path)?;
    Ok(())
}

fn now_secs() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0)
}

fn empty_gallery() -> SpecGallery {
    SpecGallery {
        version: 1,
        specs: vec![],
    }
}

fn empty_catalog() -> Catalog {
    Catalog {
        version: 1,
        entries: vec![],
    }
}

fn ok(value: Value) -> Response {
    axum::Json(value).into_response()
}

fn err(status: StatusCode, msg: &str) -> Response {
    (status, axum::Json(json!({ "error": msg }))).into_response()
}

// ── Gallery ─────────────────────────────────────────────────────────────────

/// GET /api/ui-model/gallery
pub async fn ui_model_gallery_handler(Extension(_state): Extension<Arc<AppState>>) -> Response {
    let gallery: SpecGallery = read_json(GEMMA_SPECS_PATH).unwrap_or_else(empty_gallery);
    ok(json!({ "version": gallery.version, "specs": gallery.specs }))
}

/// DELETE /api/ui-model/gallery/:id
pub async fn ui_model_gallery_delete_handler(
    Extension(_state): Extension<Arc<AppState>>,
    Path(id): Path<String>,
) -> Response {
    let mut gallery: SpecGallery = read_json(GEMMA_SPECS_PATH).unwrap_or_else(empty_gallery);
    gallery.specs.retain(|s| s.id != id);
    match write_json_atomic(
        GEMMA_SPECS_PATH,
        &json!({ "version": gallery.version, "specs": gallery.specs }),
    ) {
        Ok(_) => ok(json!({ "ok": true })),
        Err(e) => err(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("write failed: {e}"),
        ),
    }
}

// ── Catalog (promoted) ──────────────────────────────────────────────────────

/// GET /api/ui-model/catalog
pub async fn ui_model_catalog_handler(Extension(_state): Extension<Arc<AppState>>) -> Response {
    let catalog: Catalog = read_json(GEMMA_CATALOG_PATH).unwrap_or_else(empty_catalog);
    ok(json!({ "version": catalog.version, "entries": catalog.entries }))
}

/// POST /api/ui-model/catalog/promote/:id
/// Moves a spec from the gallery into the promoted catalog (seal the lens).
pub async fn ui_model_catalog_promote_handler(
    Extension(_state): Extension<Arc<AppState>>,
    Path(id): Path<String>,
) -> Response {
    let mut gallery: SpecGallery = match read_json(GEMMA_SPECS_PATH) {
        Some(g) => g,
        None => return err(StatusCode::NOT_FOUND, "gallery not available"),
    };
    let idx = match gallery.specs.iter().position(|s| s.id == id) {
        Some(i) => i,
        None => return err(StatusCode::NOT_FOUND, "spec not in gallery"),
    };
    let entry = gallery.specs.remove(idx);

    let mut catalog: Catalog = read_json(GEMMA_CATALOG_PATH).unwrap_or_else(empty_catalog);
    let promoted = CatalogEntry {
        id: entry.id.clone(),
        spec: entry.spec,
        prompt: entry.prompt,
        tags: entry.tags,
        created_at: entry.created_at,
        signature: entry.signature,
        promoted_at: now_secs(),
        label: None,
    };
    catalog.entries.push(promoted);

    if let Err(e) = write_json_atomic(
        GEMMA_SPECS_PATH,
        &json!({ "version": gallery.version, "specs": gallery.specs }),
    ) {
        return err(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("gallery write failed: {e}"),
        );
    }
    match write_json_atomic(
        GEMMA_CATALOG_PATH,
        &json!({ "version": catalog.version, "entries": catalog.entries }),
    ) {
        Ok(_) => ok(json!({ "ok": true, "id": entry.id })),
        Err(e) => err(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("catalog write failed: {e}"),
        ),
    }
}

/// DELETE /api/ui-model/catalog/:id
pub async fn ui_model_catalog_delete_handler(
    Extension(_state): Extension<Arc<AppState>>,
    Path(id): Path<String>,
) -> Response {
    let mut catalog: Catalog = read_json(GEMMA_CATALOG_PATH).unwrap_or_else(empty_catalog);
    catalog.entries.retain(|e| e.id != id);
    match write_json_atomic(
        GEMMA_CATALOG_PATH,
        &json!({ "version": catalog.version, "entries": catalog.entries }),
    ) {
        Ok(_) => ok(json!({ "ok": true })),
        Err(e) => err(
            StatusCode::INTERNAL_SERVER_ERROR,
            &format!("write failed: {e}"),
        ),
    }
}

// ── Plugin schema (sealed blob catalog) ─────────────────────────────────────

/// GET /api/ui-model/plugins — every plugin actually in the sealed blob catalog.
/// A plugin exists iff its blob is sealed here; this is NOT the same list as
/// "plugins with generated RPC methods" (some plugins, e.g. antigravity/
/// antigravity_chat, are state-only with zero methods, so they're absent
/// from the frontend's method-index but very much present as real blobs).
pub async fn ui_model_list_plugins_handler(
    Extension(_state): Extension<Arc<AppState>>,
) -> Response {
    match op_blob::catalog::read_manifest_plugin_ids_shm() {
        Some(ids) => ok(json!({ "plugins": ids })),
        None => err(
            StatusCode::SERVICE_UNAVAILABLE,
            "blob catalog manifest unavailable",
        ),
    }
}

/// GET /api/ui-model/plugin-schema/:plugin
/// The base schema is the render source: read straight from the sealed blob
/// catalog. Resolve by exact id, then by manifest prefix/contains match.
pub async fn ui_model_plugin_schema_handler(
    Extension(_state): Extension<Arc<AppState>>,
    Path(plugin): Path<String>,
) -> Response {
    let (resolved_id, schema) = match op_blob::catalog::read_plugin_schema_shm(&plugin) {
        Some(s) => (plugin.clone(), s),
        None => match resolve_plugin_by_prefix(&plugin) {
            Some((id, s)) => (id, s),
            None => {
                return err(
                    StatusCode::NOT_FOUND,
                    &format!("plugin schema not found: {plugin}"),
                )
            }
        },
    };

    ok(json!({
        "plugin": resolved_id,
        "schema_hash": schema_hash_for(&resolved_id),
        "schema": schema,
    }))
}

/// List manifest plugin ids and try a prefix/contains match for the request.
fn resolve_plugin_by_prefix(request: &str) -> Option<(String, op_state_store::PluginSchema)> {
    let ids = op_blob::catalog::read_manifest_plugin_ids_shm()?;
    let hit = ids
        .iter()
        .find(|id| id == &request || id.contains(request) || request.contains(id.as_str()))?;
    op_blob::catalog::read_plugin_schema_shm(hit).map(|s| (hit.clone(), s))
}

/// Per-plugin schema_hash from the catalog manifest (single source of truth).
fn schema_hash_for(plugin: &str) -> Option<String> {
    let bytes = std::fs::read(BLOB_MANIFEST_PATH).ok()?;
    let v: Value = serde_json::from_slice(&bytes).ok()?;
    let plugins = v.get("plugins")?.as_object()?;
    plugins
        .get(plugin)
        .and_then(|h| h.as_str())
        .map(|s| s.to_string())
}

// ── Gallery Generation API ─────────────────────────────────────────────────

use axum::response::sse::{Event, Sse};
use lazy_static::lazy_static;

lazy_static! {
    static ref GEN_PROGRESS: Arc<op_gallery_gen::RunProgress> =
        Arc::new(op_gallery_gen::RunProgress::new());
}

#[derive(Debug, Deserialize)]
pub struct GalleryGenConfig {
    pub target_count: usize,
    pub enable_mcp: bool,
    pub enable_qdrant: bool,
    pub operator_guidance: String,
}

/// POST /gallery-gen/start - Start a generation session
pub async fn start_generation(
    Extension(_state): Extension<Arc<AppState>>,
    axum::Json(config): axum::Json<GalleryGenConfig>,
) -> Result<impl IntoResponse, StatusCode> {
    // Check if already running
    if GEN_PROGRESS.running.load(Ordering::SeqCst) {
        return Err(StatusCode::CONFLICT);
    }

    // Assemble context from live blob catalog
    let ctx = match op_gallery_gen::assemble_context(
        config.enable_mcp,
        config.enable_qdrant,
        if config.operator_guidance.is_empty() {
            None
        } else {
            Some(config.operator_guidance.clone())
        },
    ) {
        Ok(ctx) => ctx,
        Err(e) => {
            tracing::error!("Failed to assemble generation context: {}", e);
            return Err(StatusCode::INTERNAL_SERVER_ERROR);
        }
    };

    let plugin_count = ctx.schemas.len();
    let catalog_hash = ctx.catalog_hash.clone();

    // Build the run config
    let run_config = op_gallery_gen::GalleryGenConfig {
        target_count: config.target_count,
        stable_core_max: 40,
        zeroclaw_endpoint: "http://localhost:8082".to_string(),
        enable_mcp: config.enable_mcp,
        enable_qdrant: config.enable_qdrant,
        max_turns: 10,"}

